const body = $json.body ?? $json;
const input = Array.isArray(body.urls) ? body.urls : (typeof body.urls === 'string' ? body.urls.split(/\r?\n|,/): []);
const seen = new Set();
const out = [];
for (const raw of input) {
  const url = String(raw ?? '').trim();
  if (!/^https?:\/\//i.test(url)) continue;
  let normalized = url;
  try {
    const u = new URL(url);
    u.hash = '';
    normalized = u.toString();
  } catch {}
  const key = normalized.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  const asin = (normalized.match(/\/(?:dp|gp\/product)\/(\w{10})(?:[/?]|$)/i) || normalized.match(/[?&]asin=(\w{10})/i) || [])[1] || null;
  out.push({ json: { batchId: $execution.id, sourceUrl: normalized, asin, status: 'queued', queuedAt: new Date().toISOString() } });
}
if (!out.length) throw new Error('No valid HTTP(S) URLs found. Send {

const p = $json.product || $json;
const source = $('Validate + Deduplicate URLs').item.json;
const product = {
  Product: p.title || null,
  AffiliateLink: p.link || source.sourceUrl,
  Rating: p.rating ?? null,
  Reviews: p.ratings_total ?? null,
  Price: p.price?.value ?? null,
  Image: p.image || null,
  Category: p.categories?.[0] || 'General',
  SourceUrl: source.sourceUrl,
  ASIN: source.asin,
  BatchId: source.batchId
};
if (!product.Product || !product.AffiliateLink) throw new Error('Rainforest did not return a usable product for '+source.sourceUrl);
return [{json: {products: [product]}}];

const raw = String($json.output || '').trim();
let item;
try { item = JSON.parse(raw.replace(/^\uFEFF/, '')); } catch (e) { throw new Error('AI returned invalid JSON: '+raw.slice(0,300)); }
if (!item.Product || !item.AffiliateLink) throw new Error('AI output missing required fields');
